import { Matcher, isDateRange } from 'react-day-picker';

export const createDateWithUTCHours = (date: Date, hours: number): Date => {
  const convertedDate = new Date(
    Date.UTC(date.getFullYear(), date.getMonth(), date.getDate(), hours)
  );
  return convertedDate;
};

export const setUTCHoursForDate = (date: Matcher | Matcher[], hours = 12) => {
  if (Array.isArray(date)) {
    return date.map((d) => createDateWithUTCHours(d as Date, hours));
  }
  if (isDateRange(date)) {
    const { from, to } = date;
    const result = {
      from: from ? createDateWithUTCHours(from, hours) : undefined,
      to: to ? createDateWithUTCHours(to, hours) : undefined,
    };
    return result;
  }
  return date ? createDateWithUTCHours(date as Date, hours) : undefined;
};
